{
  "passageId": "consciousness-cognition-ga",
  "items": [
    {
      "id": "R1",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "동일론과 기능주의가 의식의 본질을 각각 물질적 상태와 함수적 역할로 달리 보는 관점 차이이다."
    },
    {
      "id": "R2",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "함수적 역할이 같다는 말의 뜻을 입력과 출력의 쌍이 일치하는 것으로 정의한다."
    },
    {
      "id": "R3",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "실리콘 칩 로봇이라는 가상 사례로 의식의 구현 물질을 중시하지 않는 기능주의의 내용을 구체화한다."
    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "로봇이 인간과 같은 입출력 기능을 가진다는 가정으로부터 같은 의식을 가진다는 판단을 도출한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "로봇 사례에서 드러난 성질을 의식의 구현 물질은 중요하지 않다는 일반적 설명으로 정리한다."
    },
    {
      "id": "R6",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "설의 사고 실험은 기능의 동일성으로 의식의 동일성을 판단하는 기능주의를 명시적으로 반박한다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "규칙에 따라 중국어 입력에 출력을 내놓는다는 사실이 함수적 역할이 같다는 판단의 근거이다."
    },
    {
      "id": "R8",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "사고 실험에서 중국어를 모르는 사람으로 설정한 내용을 중국어를 아는 것은 아니라는 말로 다시 진술한다."
    },
    {
      "id": "R9",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "한 사람이 중국어 사용자와 함수적 역할은 같은데도 중국어를 알지는 못한다는 양면성을 제시한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "함수적 역할이 같다는 판단이 기능은 같지만 의식은 다른 사례라는 결론의 한 근거가 된다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "방 안의 사람이 중국어를 알지 못한다는 점이 의식은 다르다는 결론을 뒷받침한다."
    },
    {
      "id": "R12",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "설은 기능이 같아도 의식이 다른 반례를 제시하여 기능주의의 주장을 부정한다."
    },
    {
      "id": "R13",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "서로 대립하던 동일론·기능주의·설이 의식 논의를 몸 내부에 한정한다는 관점상의 공통점으로 묶인다."
    },
    {
      "id": "R14",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "인지가 몸 바깥의 일과 맞물린다는 사실을 제시하여 기존 입장들이 논의를 몸 내부로 한정한 점을 문제 삼는다."
    },
    {
      "id": "R15",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "노트북 파일을 열람하는 구체적 사례가 인지와 몸 바깥의 일이 맞물린다는 일반적 설명을 보여 준다."
    },
    {
      "id": "R16",
      "type": "OTHER",
      "otherName": "설명 대상",
      "reason": "확장 인지 이론과 그 이론이 설명하려는 현상을 연결하며, 구체적인 원리 적용이나 해석 내용까지 제시하는 관계는 아니다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞서 소개한 확장 인지 이론을 심적 상태·파생적 상태와 성립 조건을 통해 자세히 설명한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "자기 기억을 파악하는 사례로 심적 상태가 다른 것에 의존하지 않고 의미를 나타낸다는 성질을 구체화한다."
    },
    {
      "id": "R19",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "의미를 나타낼 때 다른 것에 의존하는지를 기준으로 심적 상태와 파생적 상태를 대비한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞서 제시한 노트북 열람 사례를 정보의 상태 유지와 주체의 기억 생성으로 더 자세히 분석한다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "노트북에 저장된 전자적 신호 형태의 정보를 파생적 상태의 구체적인 사례로 제시한다."
    },
    {
      "id": "R22",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "노트북 정보가 파생적 상태라는 설명에 열람 후에도 그 상태가 유지된다는 세부 내용을 덧붙인다."
    },
    {
      "id": "R23",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "열람 후 노트북 정보는 기존 상태를 유지하는 반면 주체에게는 새로운 기억이 생긴다는 차이를 대비한다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "열람 후에도 정보가 파생적 상태로 남는다는 사실이 파생적 상태 자체가 심적 상태로 변환되지는 않는다는 설명의 근거이다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "정보 열람 후 기억이 생기는 사례가 파생적 상태의 조작으로 심적 상태가 생겨난다는 설명을 구체적으로 보여 준다."
    },
    {
      "id": "R26",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "인지가 이루어지는 방식에 대해 상태 자체의 변환과 상태의 조작을 통한 생성을 대비한다."
    },
    {
      "id": "R27",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "몸 밖으로 확장되는지를 기준으로 심적 상태 자체와 심적 상태를 생겨나게 하는 인지 과정을 구별한다."
    },
    {
      "id": "R28",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "파생적 상태를 조작하여 심적 상태를 생성한다는 설명이 확장되는 것은 상태 자체가 아니라 과정이라는 판단을 뒷받침한다."
    },
    {
      "id": "R29",
      "type": "CONDITION",
      "otherName": "",
      "reason": "인지 과정의 외부 확장이 성립하기 위한 필수 조건으로 인지 주체와의 통합을 제시한다."
    },
    {
      "id": "R30",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "인지 과정이 반드시 주체와 통합되어야 한다는 내용을 주체 없는 인지는 불가능하다는 말로 다시 진술한다."
    },
    {
      "id": "R31",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인지 과정이 몸 밖으로 확장된다는 설명이 의식 논의의 범위를 넓혔다는 의의 평가를 뒷받침한다."
    },
    {
      "id": "R32",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "의식의 설명 범위를 몸 내부로 한정하는 기존 입장들과 몸 바깥까지 넓히는 확장 인지 이론의 관점 차이를 제시한다."
    }
  ]
}

